            std::max(a.pref, a.sum + b.pref),
            std::max(b.suff, b.sum + a.suff),
            std::max({a.best, b.best, a.suff + b.pref})
        };
    };
    auto make_node = [](int v) -> Node {
        long long vv = v;
        return {vv, vv, vv, vv};
    };

    const long long neg_inf = std::numeric_limits<long long>::lowest() / 4;
    Node identity{0, neg_inf, neg_inf, neg_inf};

    Node res = hpx::ranges::transform_reduce(
        hpx::execution::par,
        x.begin(), x.end(),
        identity,
        combine,
        make_node
    );
    return static_cast<int>(res.best);
}

int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node { long long sum, pref, suff, best; };
    auto combine = [](Node const& L, Node const& R) {
        return Node{
            L.sum + R.sum,
            std::max(L.pref, L.sum + R.pref),
            std::max(R.suff, R.sum + L.suff),
            std::max({L.best, R.best, L.suff + R.pref})
        };
    };

    std::function<Node(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Node {
            std::size_t len = r - l;
            if (len <= 2048) {
                long long sum = 0, acc = 0, pref = LLONG_MIN, suff = LLONG_MIN;

                for (std::size_t i = l; i < r; ++i) {
                    acc += x[i];
                    pref = std::max(pref, acc);
                }
                sum = acc;

                acc = 0;
                for (std::size_t i = r; i-- > l;) {
                    acc += x[i];
                    suff = std::max(suff, acc);
                }

                long long best = LLONG_MIN, cur = 0;
                for (std::size_t i = l; i < r; ++i) {
                    cur = (cur > 0 ? cur : 0) + x[i];
                    best = std::max(best, cur);
                }
                return Node{sum, pref, suff, best};
            }

            std::size_t m = l + len / 2;
            auto left = hpx::async([&] { return solve(l, m); });
            Node right = solve(m, r);
            Node L = left.get();
            return combine(L, right);
        };

    Node ans = solve(0, x.size());
    return static_cast<int>(ans.best);
}

