int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum, pref, suff, best;
    };

    auto combine = [](Node const& a, Node const& b) {
        Node c;
        c.sum  = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        c.best = std::max({a.best, b.best, a.suff + b.pref});
        return c;
    };

    // Threshold to switch to sequential processing
    constexpr std::size_t seq_cutoff = 4096;

    std::function<Node(std::size_t, std::size_t)> solve = [&](std::size_t l, std::size_t r) -> Node {
        std::size_t n = r - l;
        if (n == 0) return {0, std::numeric_limits<long long>::lowest(),
                               std::numeric_limits<long long>::lowest(),
                               std::numeric_limits<long long>::lowest()};
        if (n <= seq_cutoff) {
            long long sum = 0, pref = std::numeric_limits<long long>::lowest();
            long long curr_pref = 0;
            long long best = std::numeric_limits<long long>::lowest();
            long long curr = 0;
            long long suff = std::numeric_limits<long long>::lowest();
            long long curr_suff = 0;

            // total sum and best (Kadane), and prefix
            for (std::size_t i = l; i < r; ++i) {
                sum += x[i];
                curr = std::max<long long>(x[i], curr + x[i]);
                best = std::max(best, curr);
                curr_pref += x[i];
                pref = std::max(pref, curr_pref);
            }
            // suffix
            for (std::size_t i = r; i-- > l;) {
                curr_suff += x[i];
                suff = std::max(suff, curr_suff);
            }
            return {sum, pref, suff, best};
        }

        std::size_t m = l + n / 2;
        auto f_left  = hpx::async([&] { return solve(l, m); });
        Node right   = solve(m, r);
        Node left    = f_left.get();
        return combine(left, right);
    };

    Node res = solve(0, x.size());
    return static_cast<int>(res.best);
}

int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum;
        long long pref;
        long long suff;
        long long best;
    };

    auto seq_build = [&](std::size_t l, std::size_t r) -> Node {
        long long total = 0;
        long long pref = std::numeric_limits<long long>::lowest();
        long long suff = std::numeric_limits<long long>::lowest();
        long long best = std::numeric_limits<long long>::lowest();

        long long cur = std::numeric_limits<long long>::lowest();
        long long run = 0;

        for (std::size_t i = l; i < r; ++i) {
            total += x[i];
            pref = std::max(pref, total);

            cur = (cur == std::numeric_limits<long long>::lowest())
                    ? static_cast<long long>(x[i])
                    : std::max(cur + static_cast<long long>(x[i]),
                               static_cast<long long>(x[i]));
            best = std::max(best, cur);
        }

        run = 0;
        for (std::size_t i = r; i-- > l;) {
            run += x[i];
            suff = std::max(suff, run);
        }

        return {total, pref, suff, best};
    };

    std::function<Node(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Node {
            constexpr std::size_t grain = 4096;
            if (r - l <= grain) return seq_build(l, r);
            std::size_t m = l + (r - l) / 2;

            auto right_f = hpx::async([&] { return solve(m, r); });
            Node left = solve(l, m);
            Node right = right_f.get();

            Node res;
            res.sum = left.sum + right.sum;
            res.pref = std::max(left.pref, left.sum + right.pref);
            res.suff = std::max(right.suff, right.sum + left.suff);
            res.best = std::max({left.best, right.best, left.suff + right.pref});
            return res;
        };

    return static_cast<int>(solve(0, x.size()).best);
}

int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        int sum;
        int pref;
        int suff;
        int best;
    };

    static const int NEG_INF = std::numeric_limits<int>::min();

    auto make = [](int v) -> Node { return {v, v, v, v}; };

    auto combine = [](Node const& a, Node const& b) -> Node {
        Node c;
        c.sum = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        int cross = (a.suff == NEG_INF || b.pref == NEG_INF) ? NEG_INF
                                                             : a.suff + b.pref;
        c.best = std::max({a.best, b.best, cross});
        return c;
    };

    Node id{0, NEG_INF, NEG_INF, NEG_INF};

    Node res = hpx::transform_reduce(hpx::execution::par,
                                     x.begin(), x.end(),
                                     id, combine, make);
