    struct Seg {
        long long sum, pref, suff, best;
    };

    static constexpr long long NEG = std::numeric_limits<long long>::min() / 4;
    auto safe_add = [](long long a, long long b) {
        if (a == NEG || b == NEG) return NEG;
        return a + b;
    };

    auto combine = [&](Seg const& a, Seg const& b) -> Seg {
        Seg r;
        r.sum  = a.sum + b.sum;
        r.pref = std::max(a.pref, safe_add(a.sum, b.pref));
        r.suff = std::max(b.suff, safe_add(b.sum, a.suff));
        r.best = std::max({a.best, b.best, safe_add(a.suff, b.pref)});
        return r;
    };

    Seg id{0, NEG, NEG, NEG};

    Seg res = hpx::ranges::transform_reduce(
        hpx::execution::par, x, id, combine,
        [](int v) -> Seg {
            long long t = v;
            return {t, t, t, t};
        });

    return static_cast<int>(res.best);
}

