int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct seg {
        long long sum, pref, suff, best;
    };

    auto combine = [](seg const& L, seg const& R) -> seg {
        seg res;
        res.sum  = L.sum + R.sum;
        res.pref = std::max(L.pref, L.sum + R.pref);
        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    constexpr std::size_t chunk = 1 << 14; // tune as needed

    std::function<seg(std::vector<int>::const_iterator, std::vector<int>::const_iterator)> solve =
        [&](auto first, auto last) -> seg {
            std::size_t n = static_cast<std::size_t>(std::distance(first, last));
            if (n == 0) return {0, std::numeric_limits<long long>::lowest(),
                                std::numeric_limits<long long>::lowest(),
                                std::numeric_limits<long long>::lowest()};
            if (n == 1) {
                long long v = *first;
                return {v, v, v, v};
            }
            if (n <= chunk) {
                long long sum = 0, best = std::numeric_limits<long long>::lowest();
                long long pref = std::numeric_limits<long long>::lowest();
                long long suff = std::numeric_limits<long long>::lowest();

                // total sum and best via Kadane
                long long cur = std::numeric_limits<long long>::lowest(), cur_ended = 0;
                for (auto it = first; it != last; ++it) {
                    sum += *it;
                    cur_ended = (it == first) ? *it : std::max<long long>(*it, cur_ended + *it);
                    cur = (it == first) ? *it : std::max(cur, cur_ended);
                }
                best = cur;

                // prefix max
                long long run = 0;
                for (auto it = first; it != last; ++it) {
                    run += *it;
                    pref = std::max(pref, run);
                }
                // suffix max
                run = 0;
                for (auto it = last; it != first;) {
                    --it;
                    run += *it;
                    suff = std::max(suff, run);
                }
                return {sum, pref, suff, best};
            }

            auto mid = first + n / 2;
            auto left_fut = hpx::async(solve, first, mid);
            seg right = solve(mid, last);
            seg left = left_fut.get();
            return combine(left, right);
        };

    return static_cast<int>(solve(x.begin(), x.end()).best);
}

