            }

            std::size_t m = l + (r - l) / 2;
            // Threshold to avoid oversubscription on small ranges
            constexpr std::size_t threshold = 4096;

            if (r - l <= threshold) {
                // Sequential divide-and-conquer
                Node left  = solve(l, m);
                Node right = solve(m, r);
                return combine(left, right);
            } else {
                // Parallel: compute one side asynchronously
                auto f_right = hpx::async([&] { return solve(m, r); });
                Node left = solve(l, m);
                Node right = f_right.get();
                return combine(left, right);
            }
        };

