        return {v, v, v, v};
    };
    auto combine = [](Node const& L, Node const& R) -> Node {
        Node r;
        r.sum  = L.sum + R.sum;
        r.pref = std::max(L.pref, L.sum + R.pref);
        r.suff = std::max(R.suff, R.sum + L.suff);
