    };

    const std::size_t cutoff = 4096;

    std::function<Node(std::size_t,std::size_t)> solve = [&](std::size_t lo, std::size_t hi) -> Node {
        std::size_t n = hi - lo;
        if (n == 1) return leaf(x[lo]);
        if (n <= cutoff) {
            Node acc = leaf(x[lo]);
            for (std::size_t i = lo + 1; i < hi; ++i)
                acc = combine(acc, leaf(x[i]));
