    };

    const std::size_t cutoff = 1 << 14;

    std::function<Node(std::size_t, std::size_t)> solve = [&](std::size_t l, std::size_t r) -> Node {
        if (r - l <= cutoff) {
            long sum = 0;
            long pref = std::numeric_limits<long>::lowest();
            long suff = std::numeric_limits<long>::lowest();
            long best = std::numeric_limits<long>::lowest();

            // sum and pref
            long s = 0;
            for (std::size_t i = l; i < r; ++i) {
                s += x[i];
                if (s > pref) pref = s;
            }
            sum = s;

            // suff
            s = 0;
            for (std::size_t i = r; i-- > l;) {
                s += x[i];
                if (s > suff) suff = s;
            }

            // best (Kadane)
            long cur = std::numeric_limits<long>::lowest();
            long cur_acc = 0;
            for (std::size_t i = l; i < r; ++i) {
                cur_acc = (i == l) ? x[i] : std::max<long>(x[i], cur_acc + x[i]);
                if (cur_acc > cur) cur = cur_acc;
            }
            best = cur;

            return {sum, pref, suff, best};
        }

        std::size_t m = l + (r - l) / 2;
        auto right_f = hpx::async(solve, m, r);
        Node left = solve(l, m);
        Node right = right_f.get();

        Node res;
        res.sum = left.sum + right.sum;
        res.pref = std::max(left.pref, left.sum + right.pref);
        res.suff = std::max(right.suff, right.sum + left.suff);
        res.best = std::max({left.best, right.best, left.suff + right.pref});
        return res;
    };

    return static_cast<int>(solve(0, x.size()).best);
}

int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Info {
        long long sum, pref, suff, best;
    };

    using It = std::vector<int>::const_iterator;
    static const std::size_t cutoff = 4096;

    std::function<Info(It, It)> solve = [&](It first, It last) -> Info {
        std::size_t n = static_cast<std::size_t>(last - first);
        if (n == 0) return {0, std::numeric_limits<long long>::lowest(),
                            std::numeric_limits<long long>::lowest(),
                            std::numeric_limits<long long>::lowest()};
        if (n <= cutoff) {
            long long sum = 0, pref = std::numeric_limits<long long>::lowest();
            long long suff = std::numeric_limits<long long>::lowest();
            long long best = std::numeric_limits<long long>::lowest();
            long long cur = 0;

            // total sum and best using Kadane
            for (auto it = first; it != last; ++it) {
                sum += *it;
                cur = (it == first) ? *it : std::max<long long>(*it, cur + *it);
                best = std::max(best, cur);
            }
            // max prefix
            long long running = 0;
            for (auto it = first; it != last; ++it) {
                running += *it;
                pref = std::max(pref, running);
            }
            // max suffix
            running = 0;
            for (auto it = last; it != first;) {
                --it;
                running += *it;
                suff = std::max(suff, running);
            }
            return {sum, pref, suff, best};
        }

        It mid = first + n / 2;

        auto fleft = hpx::async(solve, first, mid);
        auto fright = hpx::async(solve, mid, last);

        Info L = fleft.get();
        Info R = fright.get();

        Info res;
        res.sum = L.sum + R.sum;
        res.pref = std::max(L.pref, L.sum + R.pref);
        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    return static_cast<int>(solve(x.begin(), x.end()).best);
}

