        c.sum  = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        c.best = std::max({a.best, b.best, a.suff + b.pref});
        return c;
    };

    constexpr std::size_t threshold = 8192;

    std::function<Agg(std::size_t, std::size_t)> solve = [&](std::size_t l, std::size_t r) -> Agg {
        std::size_t n = r - l;
        if (n == 1) {
            long long v = x[l];
            return Agg{v, v, v, v};
        }
        if (n <= threshold) {
            Agg acc{0, std::numeric_limits<long long>::lowest(),
                       std::numeric_limits<long long>::lowest(),
                       std::numeric_limits<long long>::lowest()};
            for (std::size_t i = l; i < r; ++i) {
                long long v = x[i];
                Agg cur{v, v, v, v};
                acc = (i == l) ? cur : combine(acc, cur);
            }
            return acc;
        }
        std::size_t m = l + n / 2;
        auto fleft = hpx::async([&] { return solve(l, m); });
        Agg right = solve(m, r);
        Agg left = fleft.get();
        return combine(left, right);
    };

    Agg res = solve(0, x.size());
    return static_cast<int>(res.best);
}

