int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum, pref, suff, best;
    };

    auto combine = [](Node const& a, Node const& b) -> Node {
        Node c;
        c.sum  = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        c.best = std::max({a.best, b.best, a.suff + b.pref});
        return c;
    };

    struct Solver {
        std::vector<int> const& v;
        std::size_t cutoff;

        Node sequential(std::size_t l, std::size_t r) const {
            Node n{0, std::numeric_limits<long long>::min(),
                      std::numeric_limits<long long>::min(),
                      std::numeric_limits<long long>::min()};
            long long s = 0, best_pref = std::numeric_limits<long long>::min();
            for (std::size_t i = l, end = r; i < end; ++i) {
                s += v[i];
                if (s > best_pref) best_pref = s;
            }
            long long t = 0, best_suff = std::numeric_limits<long long>::min();
            for (std::size_t i = r; i-- > l;) {
                t += v[i];
                if (t > best_suff) best_suff = t;
            }
            long long total = 0, max_ending_here = std::numeric_limits<long long>::min(), max_so_far = std::numeric_limits<long long>::min();
            long long cur = 0;
            for (std::size_t i = l, end = r; i < end; ++i) {
                total += v[i];
                cur = (i == l) ? v[i] : std::max<long long>(v[i], cur + v[i]);
                if (cur > max_so_far) max_so_far = cur;
            }
            n.sum = total;
            n.pref = best_pref;
            n.suff = best_suff;
            n.best = max_so_far;
            return n;
        }

        Node operator()(std::size_t l, std::size_t r) const {
            std::size_t n = r - l;
            if (n == 0) {
                return Node{0, std::numeric_limits<long long>::min(),
                               std::numeric_limits<long long>::min(),
                               std::numeric_limits<long long>::min()};
            }
            if (n <= cutoff) return sequential(l, r);

            std::size_t m = l + n / 2;
            auto left_f = hpx::async(&Solver::operator(), this, l, m);
            Node right = (*this)(m, r);
            Node left = left_f.get();

            return combine(left, right);
        }
    };

    Solver solver{x, 4096};
    Node res = solver(0, x.size());
    return static_cast<int>(res.best);
}

