int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Result {
        long long max_sum;
        long long prefix;
        long long suffix;
        long long total;
    };

    auto combine = [](Result const& L, Result const& R) {
        return Result{
            std::max({L.max_sum, R.max_sum, L.suffix + R.prefix}),
            std::max(L.prefix, L.total + R.prefix),
            std::max(R.suffix, R.total + L.suffix),
            L.total + R.total
        };
    };

    const std::size_t cutoff = 2048;

    std::function<Result(std::size_t, std::size_t)> solve =
        [&](std::size_t b, std::size_t e) -> Result {
            std::size_t n = e - b;
            if (n == 0) return {std::numeric_limits<long long>::lowest(), 0, 0, 0};
            if (n <= cutoff) {
                long long total = 0, pref = std::numeric_limits<long long>::lowest();
                long long suff = std::numeric_limits<long long>::lowest();
                long long cur_pref = 0, cur_suff = 0, best = std::numeric_limits<long long>::lowest();

                // prefix and best
                for (std::size_t i = b; i < e; ++i) {
                    total += x[i];
                    cur_pref += x[i];
                    pref = std::max(pref, cur_pref);
                    best = std::max(best, cur_pref);
                    if (cur_pref < 0) cur_pref = 0;
                }
                // suffix
                for (std::size_t i = e; i-- > b;) {
                    cur_suff += x[i];
                    suff = std::max(suff, cur_suff);
                    if (cur_suff < 0) cur_suff = 0;
                }
                // Recompute best (Kadane) precisely
                long long kad = std::numeric_limits<long long>::lowest(), cur = 0;
                for (std::size_t i = b; i < e; ++i) {
                    cur = (cur > 0 ? cur + x[i] : x[i]);
                    kad = std::max(kad, cur);
                }
                return {kad, pref, suff, total};
            }

            std::size_t m = b + n / 2;
            auto left_f = hpx::async(solve, b, m);
            Result right = solve(m, e);
            Result left = left_f.get();
            return combine(left, right);
        };

    return static_cast<int>(solve(0, x.size()).max_sum);
}

