        return Res{
            L.sum + R.sum,
            std::max(L.pref, L.sum + R.pref),
            std::max(R.suff, R.sum + L.suff),
            std::max(std::max(L.best, R.best), L.suff + R.pref)
        };
    };

    const std::size_t threshold = 1u << 14;

    std::function<Res(std::size_t, std::size_t)> solve = [&](std::size_t lo, std::size_t hi) -> Res {
        std::size_t n = hi - lo;
        if (n == 1) {
            long long v = x[lo];
            return {v, v, v, v};
        }
        if (n <= threshold) {
            long long sum = 0;
            for (std::size_t i = lo; i < hi; ++i) sum += x[i];

            long long s = 0, pref = x[lo];
            for (std::size_t i = lo; i < hi; ++i) { s += x[i]; if (s > pref) pref = s; }

            s = 0;
            long long suff = x[hi - 1];
            for (std::size_t i = hi; i-- > lo;) { s += x[i]; if (s > suff) suff = s; }

            long long cur = x[lo], best = x[lo];
            for (std::size_t i = lo + 1; i < hi; ++i) {
                cur = std::max<long long>(x[i], cur + x[i]);
                if (cur > best) best = cur;
            }
            return {sum, pref, suff, best};
        }

        std::size_t mid = lo + n / 2;
        auto fL = hpx::async(hpx::launch::async, solve, lo, mid);
        Res R = solve(mid, hi);
        Res L = fL.get();
        return combine(L, R);
    };

