        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    constexpr std::size_t threshold = 2048;

    std::function<Node(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Node {
            if (r - l == 1) {
                long long v = x[l];
                return {v, v, v, v};
            }
            if (r - l <= threshold) {
                // sequential divide-and-conquer
                std::size_t m = l + (r - l) / 2;
                Node L = solve(l, m);
                Node R = solve(m, r);
                return combine(L, R);
            }
            std::size_t m = l + (r - l) / 2;
            auto left_f = hpx::async([&]() { return solve(l, m); });
            Node R = solve(m, r);
            Node L = left_f.get();
            return combine(L, R);
        };

    Node res = solve(0, x.size());
    return static_cast<int>(res.best);
}

