int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum;
        long long best;
        long long pref;
        long long suff;
    };

    auto combine = [](Node const& L, Node const& R) -> Node {
        Node res;
        res.sum  = L.sum + R.sum;
        res.pref = std::max(L.pref, L.sum + R.pref);
        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    const std::size_t cutoff = 4096;

    std::function<Node(std::size_t, std::size_t)> solve = [&](std::size_t l, std::size_t r) -> Node {
        std::size_t n = r - l;
        if (n <= cutoff) {
            long long total = 0;
            long long pref = std::numeric_limits<long long>::lowest();
            long long best = std::numeric_limits<long long>::lowest();

            long long curr = std::numeric_limits<long long>::lowest();
            long long run = 0;
            for (std::size_t i = l; i < r; ++i) {
                total += x[i];
                run += x[i];
                pref = std::max(pref, run);

                if (i == l) curr = x[i];
                else curr = std::max<long long>(x[i], curr + x[i]);
                best = std::max(best, curr);
            }
            long long suff = std::numeric_limits<long long>::lowest();
            long long run2 = 0;
            for (std::size_t i = r; i-- > l; ) {
                run2 += x[i];
                suff = std::max(suff, run2);
            }
            return {total, best, pref, suff};
        }

        std::size_t m = l + n / 2;
        auto left_f = hpx::async(solve, l, m);
        Node right = solve(m, r);
        Node left = left_f.get();
        return combine(left, right);
    };

    return static_cast<int>(solve(0, x.size()).best);
}

