int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Seg {
        long long sum, pref, suff, best;
    };
    auto combine = [](Seg const& L, Seg const& R) -> Seg {
        return {
            L.sum + R.sum,
            std::max(L.pref, L.sum + R.pref),
            std::max(R.suff, R.sum + L.suff),
            std::max({L.best, R.best, L.suff + R.pref})
        };
    };

    constexpr std::size_t cutoff = 4096;

    auto sequential = [&](std::size_t l, std::size_t r) -> Seg {
        long long sum = 0;
        long long pref = std::numeric_limits<long long>::lowest();
        long long suff = std::numeric_limits<long long>::lowest();
        long long best = std::numeric_limits<long long>::lowest();

        long long s = 0;
        for (std::size_t i = l; i < r; ++i) {
            s += x[i];
            pref = std::max(pref, s);
        }
        sum = s;

        long long t = 0;
        for (std::size_t i = r; i-- > l;) {
            t += x[i];
            suff = std::max(suff, t);
        }

        long long cur = 0;
        for (std::size_t i = l; i < r; ++i) {
            cur = std::max<long long>(x[i], cur + x[i]);
            best = std::max(best, cur);
        }
        return {sum, pref, suff, best};
    };

    std::function<Seg(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Seg {
            std::size_t n = r - l;
            if (n <= 1) {
                long long v = x[l];
                return {v, v, v, v};
            }
            if (n <= cutoff) return sequential(l, r);

            std::size_t m = l + n / 2;
            auto left_f = hpx::async(solve, l, m);
            Seg right = solve(m, r);
            Seg left = left_f.get();
            return combine(left, right);
        };

    return static_cast<int>(solve(0, x.size()).best);
