    if (x.empty()) return 0;

    struct Node {
        long long sum, pref, suff, best;
    };

    auto combine = [](Node const& a, Node const& b) -> Node {
        Node c;
        c.sum = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        c.best = std::max({a.best, b.best, a.suff + b.pref});
        return c;
    };

    size_t const cutoff = 4096;

    std::function<Node(size_t, size_t)> solve = [&](size_t l, size_t r) -> Node {
        size_t n = r - l;
        if (n == 0) return {0, std::numeric_limits<long long>::lowest(),
                            std::numeric_limits<long long>::lowest(),
                            std::numeric_limits<long long>::lowest()};
        if (n <= cutoff) {
            long long sum = 0, pref = std::numeric_limits<long long>::lowest();
            long long suff = std::numeric_limits<long long>::lowest();
            long long best = std::numeric_limits<long long>::lowest();

            long long cur_pref = std::numeric_limits<long long>::lowest();
            long long cur = 0;
            for (size_t i = l; i < r; ++i) {
                sum += x[i];
                cur = (i == l) ? x[i] : std::max<long long>(x[i], cur + x[i]);
                best = std::max(best, cur);
                cur_pref = (i == l) ? x[i] : cur_pref + x[i];
                pref = std::max(pref, cur_pref);
            }
            long long cur_suff = std::numeric_limits<long long>::lowest();
            for (size_t i = r; i-- > l;) {
                cur_suff = (i + 1 == r) ? x[i] : cur_suff + x[i];
                suff = std::max(suff, cur_suff);
            }
            return {sum, pref, suff, best};
        }

        size_t m = l + n / 2;
        auto left_f = hpx::async(solve, l, m);
        Node right = solve(m, r);
        Node left = left_f.get();
        return combine(left, right);
    };

    return static_cast<int>(solve(0, x.size()).best);
}

