int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum, pref, suff, best;
    };

    struct Solver {
        std::vector<int> const& a;
        std::size_t cutoff = 10000;

        Node combine(Node const& L, Node const& R) const {
            Node res;
            res.sum  = L.sum + R.sum;
            res.pref = std::max(L.pref, L.sum + R.pref);
            res.suff = std::max(R.suff, R.sum + L.suff);
            res.best = std::max({L.best, R.best, L.suff + R.pref});
            return res;
        }

        Node serial(std::size_t l, std::size_t r) const {
            Node res{a[l], a[l], a[l], a[l]};
            for (std::size_t i = l + 1; i < r; ++i) {
                Node cur{a[i], a[i], a[i], a[i]};
                res = combine(res, cur);
            }
            return res;
        }

        Node solve(std::size_t l, std::size_t r) const {
            std::size_t n = r - l;
            if (n == 1) {
                long long v = a[l];
                return Node{v, v, v, v};
            }
            if (n <= cutoff) return serial(l, r);

            std::size_t m = l + n / 2;
            auto fL = hpx::async([this, l, m] { return this->solve(l, m); });
            Node R = solve(m, r);
            Node L = fL.get();
            return combine(L, R);
        }
    };

    Solver s{ x };
    return static_cast<int>(s.solve(0, x.size()).best);
}

