int maximumSubarray(std::vector<int> const& x) {
    if (x.empty()) return 0;

    struct Node {
        long long sum, pref, suff, best;
    };
    auto combine = [](Node const& a, Node const& b) {
        Node c;
        c.sum  = a.sum + b.sum;
        c.pref = std::max(a.pref, a.sum + b.pref);
        c.suff = std::max(b.suff, b.sum + a.suff);
        c.best = std::max({a.best, b.best, a.suff + b.pref});
        return c;
    };

    const std::size_t cutoff = 1 << 14;

    std::function<Node(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Node {
            const std::size_t n = r - l;
            if (n == 1) {
                long long v = x[l];
                return {v, v, v, v};
            }
            if (n <= cutoff) {
                Node acc{0, std::numeric_limits<long long>::min(),
                         std::numeric_limits<long long>::min(),
                         std::numeric_limits<long long>::min()};
                long long running = 0, best_pref = std::numeric_limits<long long>::min();
                long long pref_sum = 0, best_suff = std::numeric_limits<long long>::min();
                long long curr_best = std::numeric_limits<long long>::min();
                long long total = 0;

                // total, pref, best
                for (std::size_t i = l; i < r; ++i) {
                    total += x[i];
                    pref_sum += x[i];
                    best_pref = std::max(best_pref, pref_sum);
                    running = (i == l) ? x[i] : std::max<long long>(x[i], running + x[i]);
                    curr_best = std::max(curr_best, running);
                }
                // suff
                long long suff_sum = 0;
                for (std::size_t i = r; i-- > l;) {
                    suff_sum += x[i];
                    best_suff = std::max(best_suff, suff_sum);
                }
                acc.sum = total;
                acc.pref = best_pref;
                acc.suff = best_suff;
                acc.best = curr_best;
                return acc;
            }

            std::size_t m = l + (r - l) / 2;
            auto f_left  = hpx::async(solve, l, m);
            Node right   = solve(m, r);
            Node left    = f_left.get();
            return combine(left, right);
        };

    Node res = (x.size() == 1) ? Node{x[0], x[0], x[0], x[0]} : solve(0, x.size());
    return static_cast<int>(res.best);
}

