int maximumSubarray(std::vector<int> const& x) {
    using i64 = long long;
    struct Node { i64 sum, pref, suff, best; };

    auto make = [](int v) -> Node {
        i64 a = v;
        return {a, a, a, a};
    };
    auto merge = [](Node const& L, Node const& R) -> Node {
        Node res;
        res.sum  = L.sum + R.sum;
        res.pref = std::max(L.pref, L.sum + R.pref);
        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    std::size_t n = x.size();
    if (n == 0) return 0;

    constexpr std::size_t cutoff = 1 << 14;

    std::function<Node(std::size_t, std::size_t)> solve;
    solve = [&](std::size_t l, std::size_t r) -> Node {
        if (r - l <= cutoff) {
            Node res = make(x[l]);
            for (std::size_t i = l + 1; i < r; ++i)
                res = merge(res, make(x[i]));
            return res;
        }
        std::size_t m = l + (r - l) / 2;
        auto left_f  = hpx::async([&] { return solve(l, m); });
        Node right   = solve(m, r);
        Node left    = left_f.get();
        return merge(left, right);
    };

    return static_cast<int>(solve(0, n).best);
}

