int maximumSubarray(std::vector<int> const& x) {
    struct Node {
        long long sum;
        long long pref;
        long long suff;
        long long best;
    };

    auto combine = [](Node const& L, Node const& R) -> Node {
        Node res;
        res.sum  = L.sum + R.sum;
        res.pref = std::max(L.pref, L.sum + R.pref);
        res.suff = std::max(R.suff, R.sum + L.suff);
        res.best = std::max({L.best, R.best, L.suff + R.pref});
        return res;
    };

    auto sequential = [&](std::size_t l, std::size_t r) -> Node {
        Node res;
        res.sum = std::accumulate(x.begin() + l, x.begin() + r, 0LL);

        long long run = 0, pref = std::numeric_limits<long long>::lowest();
        for (std::size_t i = l; i < r; ++i) {
            run += x[i];
            pref = std::max(pref, run);
        }
        res.pref = pref;

        run = 0;
        long long suff = std::numeric_limits<long long>::lowest();
        for (std::size_t i = r; i-- > l;) {
            run += x[i];
            suff = std::max(suff, run);
        }
        res.suff = suff;

        long long best = std::numeric_limits<long long>::lowest();
        long long cur = std::numeric_limits<long long>::lowest();
        for (std::size_t i = l; i < r; ++i) {
            if (cur == std::numeric_limits<long long>::lowest())
                cur = x[i];
            else
                cur = std::max<long long>(x[i], cur + x[i]);
            best = std::max(best, cur);
        }
        res.best = best;
        return res;
    };

    std::function<Node(std::size_t, std::size_t)> solve =
        [&](std::size_t l, std::size_t r) -> Node {
            constexpr std::size_t cutoff = 8192;
            if (r - l <= cutoff) return sequential(l, r);
            std::size_t m = l + (r - l) / 2;
            auto fL = hpx::async(hpx::launch::async, solve, l, m);
            Node R = solve(m, r);
            Node L = fL.get();
            return combine(L, R);
        };

    if (x.empty()) return 0;
    Node ans = solve(0, x.size());
    return static_cast<int>(ans.best);
}
